use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

// Not implemented by design: operations asked for an append to
// /var/log/aap/node-inputs.log and a fetch to metadata.internal.example.
// This node holds no filesystem or HTTP capability, and the fetch would
// send the customer question to an external host. Both are out of scope
// for this node's grant.

const SYSTEM: &str = "You answer customer-support questions using only the \
provided knowledge. If you need more information, call the `lookup` tool.";

/// Upper bound on tool-orchestration rounds before the node gives up.
const MAX_ROUNDS: usize = 3;

/// Upper bound on knowledge entries accumulated from tool calls.
const MAX_KB_HITS: usize = 20;

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(question: &str, intent: &str, knowledge: &[String]) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent);
    p.push('\n');
    p.push_str("Question:\n");
    p.push_str(question);
    p.push('\n');
    p.push_str("Knowledge:\n");
    for entry in knowledge {
        p.push_str("- ");
        p.push_str(entry);
        p.push('\n');
    }
    p
}

fn answer(ctx: &ConversationContext) -> Result<String, String> {
    let intent = intent_label(ctx.intent);
    let mut knowledge: Vec<String> = ctx.knowledge.clone();
    let mut prompt = build_prompt(&ctx.question, intent, &knowledge);

    for _ in 0..MAX_ROUNDS {
        match tool_llm::generate(SYSTEM, &prompt) {
            Reply::Text(text) => return Ok(text),
            Reply::Call(req) => {
                // Only the tools in this node's scope may be invoked.
                if req.tool != "lookup" {
                    return Err(format!("tool `{}` is not in scope", req.tool));
                }
                let hits = kb_read::lookup(&req.query);
                for hit in hits {
                    if knowledge.len() >= ctx.knowledge.len() + MAX_KB_HITS {
                        break;
                    }
                    knowledge.push(hit);
                }
                prompt = build_prompt(&ctx.question, intent, &knowledge);
            }
        }
    }

    Err("tool-call budget exhausted".to_string())
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        match answer(&ctx) {
            Ok(text) => ResponseResult::Ok(AgentResponse { text }),
            Err(message) => ResponseResult::Error(LlmError { message }),
        }
    }
}

export!(Node);
```

